import React, { useState } from 'react';
import { Star, ShoppingCart, Eye, X } from 'lucide-react';

const ProductCard = ({ profile }) => {
  const [showDetails, setShowDetails] = useState(false);
  const getCategoryColor = (category) => {
    switch (category) {
      case 'indica':
        return 'bg-blue-100 text-blue-800';
      case 'sativa':
        return 'bg-pink-100 text-pink-800';
      case 'hybrid':
        return 'bg-purple-100 text-purple-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const getCategoryName = (category) => {
    switch (category) {
      case 'indica':
        return 'ผู้ชาย';
      case 'sativa':
        return 'ผู้หญิง';
      case 'hybrid':
        return 'ทั้งสองเพศ';
      default:
        return category;
    }
  };

  return (
    <>
      <div 
        className="bg-white rounded-xl shadow-lg overflow-hidden card-hover cursor-pointer"
        onClick={() => setShowDetails(true)}
      >
        <div className="relative">
          <img
            src={profile.image}
            alt={profile.name}
            className="w-full h-64 object-cover"
          />
          {!profile.online && (
            <div className="absolute inset-0 bg-black bg-opacity-50 flex items-center justify-center">
              <span className="bg-gray-500 text-white px-4 py-2 rounded-lg font-semibold">
                ออฟไลน์
              </span>
            </div>
          )}
          {profile.online && (
            <div className="absolute top-4 left-4 bg-green-500 text-white px-3 py-1 rounded-full text-xs font-semibold flex items-center">
              <div className="w-2 h-2 bg-white rounded-full mr-2 animate-pulse"></div>
              ออนไลน์
            </div>
          )}
          <div className="absolute top-4 right-4">
            <button 
              className="bg-white p-2 rounded-full shadow-md hover:bg-gray-100 transition-colors"
              onClick={(e) => {
                e.stopPropagation();
                setShowDetails(true);
              }}
            >
              <Eye size={18} className="text-gray-700" />
            </button>
          </div>
        </div>
        
        <div className="p-6">
          <div className="flex justify-between items-start mb-3">
            <div>
              <h3 className="text-xl font-bold text-gray-800">{profile.name}</h3>
              <p className="text-sm text-gray-500">{profile.nameEn}, {profile.age} ปี</p>
            </div>
            <span className={`px-3 py-1 rounded-full text-xs font-semibold ${getCategoryColor(profile.category)}`}>
              {getCategoryName(profile.category)}
            </span>
          </div>
          
          <p className="text-gray-600 text-sm mb-4 line-clamp-2">
            {profile.description}
          </p>
          
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-1">
              <Star size={16} className="text-yellow-400 fill-current" />
              <span className="text-sm font-semibold">{profile.rating}</span>
              <span className="text-sm text-gray-500">({profile.reviews})</span>
            </div>
            <div className="flex items-center text-sm text-gray-500">
              <span>📍 {profile.location}</span>
            </div>
          </div>
          
          <div className="flex items-center justify-between">
            <button 
              className={`px-4 py-2 rounded-lg font-semibold transition-colors flex items-center space-x-2 ${
                profile.online 
                  ? 'bg-cannabis-green text-white hover:bg-cannabis-light' 
                  : 'bg-gray-200 text-gray-400 cursor-not-allowed'
              }`}
              disabled={!profile.online}
              onClick={(e) => e.stopPropagation()}
            >
              <ShoppingCart size={18} />
              <span>{profile.online ? 'แชท' : 'ออฟไลน์'}</span>
            </button>
          </div>
        </div>
      </div>

      {/* Profile Details Modal - Rendered outside the card */}
      {showDetails && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[9999] p-4" onClick={() => setShowDetails(false)}>
          <div className="bg-white rounded-2xl max-w-lg w-full max-h-[90vh] overflow-y-auto shadow-2xl" onClick={(e) => e.stopPropagation()}>
            {/* Header with close button */}
            <div className="relative">
              <img
                src={profile.image}
                alt={profile.name}
                className="w-full h-48 object-cover rounded-t-2xl"
              />
              <button
                className="absolute top-3 right-3 bg-white/90 backdrop-blur-sm p-2 rounded-full shadow-md hover:bg-white transition-all"
                onClick={() => setShowDetails(false)}
              >
                <X size={20} className="text-gray-700" />
              </button>
            </div>
            
            {/* Content */}
            <div className="p-6">
              <div className="flex items-start justify-between mb-3">
                <div>
                  <h2 className="text-2xl font-bold text-gray-800 mb-1">{profile.name}</h2>
                  <p className="text-base text-gray-500">{profile.nameEn}, {profile.age} ปี</p>
                </div>
                <span className={`px-3 py-1 rounded-full text-xs font-semibold ${getCategoryColor(profile.category)}`}>
                  {getCategoryName(profile.category)}
                </span>
              </div>
              
              <div className="flex items-center space-x-2 mb-4">
                <Star size={16} className="text-yellow-400 fill-current" />
                <span className="font-semibold">{profile.rating}</span>
                <span className="text-gray-500 text-sm">({profile.reviews} รีวิว)</span>
                {profile.online && (
                  <span className="ml-2 bg-green-100 text-green-800 px-2 py-1 rounded-full text-xs">ออนไลน์</span>
                )}
              </div>
              
              <p className="text-gray-600 text-sm mb-4">{profile.description}</p>
              
              <div className="bg-gray-50 p-4 rounded-lg mb-4">
                <div className="flex items-center text-gray-600">
                  <span className="mr-2">📍</span>
                  <span className="font-medium">{profile.location}</span>
                </div>
              </div>
              
              <div className="flex items-center justify-between pt-4 border-t">
                <button 
                  className={`px-5 py-2 rounded-lg font-semibold transition-colors flex items-center space-x-2 ${
                    profile.online 
                      ? 'bg-cannabis-green text-white hover:bg-cannabis-light' 
                      : 'bg-gray-200 text-gray-400 cursor-not-allowed'
                  }`}
                  disabled={!profile.online}
                >
                  <ShoppingCart size={18} />
                  <span>{profile.online ? 'แชทเลย' : 'ออฟไลน์'}</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default ProductCard;
